    v  = float(str(STOCK["tw_volume"]).replace(",", ""))
    ma = float(str(TECHNICAL["vol_ma5"]).replace(",", ""))
    if ma <= 0:
        return "量能待確認", "#607D8B"
    d = (v / ma - 1) * 100
    if d >= 20:  return f"明顯放量 (+{d:.0f}% vs 均量)", "#F44336"
    if d >= 3:   return f"量增 (+{d:.0f}% vs 均量)",     "#4CAF50"
    if d > -3:   return "量能持平 (約當均量)",            "#607D8B"
    if d > -20:  return f"量縮 ({d:.0f}% vs 均量)",       "#607D8B"
    return f"明顯量縮 ({d:.0f}% vs 均量)", "#FF9800"
